s32 nUserSession::CPacket_S2C_CHANGE_CAP_TO_GP_RES::ReadPacket(CPacket* pPacket) {
    if (::nPacket::Read(*pPacket, m_usError) != 0) {
        if (::nPacket::Read(*pPacket, m_unResult) != 0) {
            if (::nPacket::Read(*pPacket, m_unChangeListID) != 0) {
                if (::nPacket::Read(*pPacket, m_unGP) != 0) {
                    if (::nPacket::Read(*pPacket, m_unCAP) != 0) {
                        m_bIsReceived = true;
                        return 1;
                    }
                }
            }
        }
        return m_usError != 0;
    } else {
        return 0;
    }
}

