s32 nUserSession::CPacket_S2C_ENCOUNTER_PAWN_NOTICE::ReadPacket(CPacket* pPacket) {
    if (::nPacket::Read(*pPacket, m_usError) != 0) {
        if (::nPacket::Read(*pPacket, m_LayoutId.m_unStageID) != 0) {
            if (::nPacket::Read(*pPacket, m_LayoutId.m_ucLayerNo) != 0) {
                if (::nPacket::Read(*pPacket, m_LayoutId.m_unGroupID) != 0) {
                    if (::nPacket::Read(*pPacket, m_info.m_ulLv) != 0) {
                        if (::nPacket::Read(*pPacket, m_info.m_ulLvBand) != 0) {
                            if (::nPacket::Read(*pPacket, m_info.m_ulThinkID) != 0) {
                                m_bIsReceived = true;
                                return 1;
                            }
                        }
                    }
                }
            }
        }
        return m_usError != 0;
    } else {
        return 0;
    }
}

