s32 nUserSession::CPacket_S2C_EXCHANGE_OM_INSTANT_KEY_VALUE_RES::ReadPacket(CPacket* pPacket) {
    if (::nPacket::Read(*pPacket, m_usError) != 0) {
        if (::nPacket::Read(*pPacket, m_nResult) != 0) {
            if (::nPacket::Read(*pPacket, m_unStageId) != 0) {
                if (::nPacket::Read(*pPacket, m_Value.m_ulKey) != 0) {
                    if (::nPacket::Read(*pPacket, m_Value.m_ulValue) != 0) {
                        if (::nPacket::Read(*pPacket, m_ulValueOld) != 0) {
                            m_bIsReceived = true;
                            return 1;
                        }
                    }
                }
            }
        }
        return m_usError != 0;
    } else {
        return 0;
    }
}

