s32 nUserSession::CPacket_S2C_GP_COURSE_START_PARTY_NTC::ReadPacket(CPacket* pPacket) {
    if (::nPacket::Read(*pPacket, m_usError) != 0) {
        if (::nPacket::Read(*pPacket, m_ucMemberIndex) != 0) {
            if (::nPacket::Read(*pPacket, m_unCourseID) != 0) {
                if (::nPacket::Read(*pPacket, m_unannounceType) != 0) {
                    if (::nPacket::Read(*pPacket, m_ullFinishDateTime) != 0) {
                        m_bIsReceived = true;
                        return 1;
                    }
                }
            }
        }
        return m_usError != 0;
    } else {
        return 0;
    }
}

