s32 nUserSession::CPacket_S2C_QUEST_COMPLETE_NOTICE::ReadPacket(CPacket* pPacket) {
    if (::nPacket::Read(*pPacket, m_usError) != 0) {
        if (::nPacket::Read(*pPacket, m_unQuestScheduleId) != 0) {
            if (::nPacket::Read(*pPacket, m_ucRandomRewardNum) != 0) {
                if (::nPacket::Read(*pPacket, m_ucChargeRewardNum) != 0) {
                    if (::nPacket::Read(*pPacket, m_ucProgressBonusNum) != 0) {
                        if (::nPacket::Read(*pPacket, m_ucIsRepeatReward) != 0) {
                            if (::nPacket::Read(*pPacket, m_ucIsUndiscoverReward) != 0) {
                                if (::nPacket::Read(*pPacket, m_ucIsHelpReward) != 0) {
                                    if (::nPacket::Read(*pPacket, m_ucIsPartyBonus) != 0) {
                                        m_bIsReceived = true;
                                        return 1;
                                    }
                                }
                            }
                        }
                    }
                }
            }
        }
        return m_usError != 0;
    } else {
        return 0;
    }
}

