    if (::nPacket::Read(*pPacket, m_usError) != 0) {
        if (::nPacket::Read(*pPacket, m_nResult) != 0) {
            if (::nPacket::Read(*pPacket, m_ucSlotNo) != 0) {
                if (::nPacket::Read(*pPacket, m_unAbilityID) != 0) {
                    if (::nPacket::Read(*pPacket, m_ucAbilityLv) != 0) {
                        m_bIsReceived = true;
                        return 1;
                    }
                }
            }
        }
        return m_usError != 0;
    } else {
        return 0;
    }
