s32 nUserSession::CPacket_S2C_STAMP_BONUS_CHECK_RES::ReadPacket(CPacket* pPacket) {
    if (::nPacket::Read(*pPacket, m_usError) != 0) {
        if (::nPacket::Read(*pPacket, m_nResult) != 0) {
            if (::nPacket::Read(*pPacket, m_usTotalStampNum) != 0) {
                if (::nPacket::Read(*pPacket, m_ucisRecieveBonusDaily) != 0) {
                    if (::nPacket::Read(*pPacket, m_ucisRecieveBonusTotal) != 0) {
                        m_bIsReceived = true;
                        return 1;
                    }
                }
            }
        }
        return m_usError != 0;
    } else {
        return 0;
    }
}

